function pageFaqs(locale: string, key: keyof typeof faqs) {
  return locale === "ar" ? localizedFaqs.ar[key] : locale === "fr" ? localizedFaqs.fr[key] : faqs[key];
}

function localeCopy(locale: string) {
  return translations[(["en", "ar", "fr"].includes(locale) ? locale : "en") as Locale];
}

function localizedMarketNames(locale: string) {
  if (locale === "ar") {
    return {
      lb: "لبنان",
      ae: "الإمارات العربية المتحدة",
      sa: "السعودية",
      us: "الولايات المتحدة",
      fr: "فرنسا"
    };
  }
  if (locale === "fr") {
    return {
      lb: "Liban",
      ae: "Émirats arabes unis",
      sa: "Arabie saoudite",
      us: "États-Unis",
      fr: "France"
    };
  }
  return Object.fromEntries(Object.entries(markets).map(([key, value]) => [key, value.label])) as Record<keyof typeof markets, string>;
}

function PageHero({ eyebrow, title, lead, children }: { eyebrow: string; title: string; lead: string; children?: ReactNode }) {
  return <section className={`page-hero ${children ? "page-hero-with-media" : ""}`}><div className="shell">{children ? <div className="page-hero-layout"><SectionIntro eyebrow={eyebrow} title={title} lede={lead} level="h1" />{children}</div> : <SectionIntro eyebrow={eyebrow} title={title} lede={lead} level="h1" />}</div></section>;
}

type CtaMode = "erp" | "discovery" | "matchpulse" | "contact";

function PageCta({ locale, title = "Ready to make the next step clearer?", mode = "contact" }: { locale: string; title?: string; mode?: CtaMode }) {
  const copy = localeCopy(locale);
  const localized = locale === "ar" ? {
    eyebrow: "لنبدأ محادثة", lead: "أخبرنا بما يحتاج فريقك إلى ربطه وسنحدد الخطوة التالية.", erp: "ابدأ تجربة ERP لمدة 14 يوماً", discovery: "احجز مكالمة اكتشاف", matchpulse: "احجز عرض MatchPulse", contact: "تواصل معنا"
  } : locale === "fr" ? {
    eyebrow: "Parlons-en", lead: "Dites-nous ce que votre équipe veut relier et nous définirons la suite.", erp: "Démarrer l'essai ERP de 14 jours", discovery: "Réserver un appel découverte", matchpulse: "Réserver une démo MatchPulse", contact: "Nous contacter"
  } : {
    eyebrow: "Start a conversation", lead: "Tell us what your team wants to connect and we will map the next step.", erp: "Start your 14-day ERP trial", discovery: "Book a discovery call", matchpulse: "Book a MatchPulse demo", contact: "Talk to us"
  };
  const label = localized[mode];
  const href = mode === "erp" ? erpUrl : localizedPath(locale, mode === "matchpulse" ? "/contact/?interest=MatchPulse" : "/contact/");
  return <section className="cta"><span className="eyebrow">{localized.eyebrow}</span><h2>{title}</h2><p>{localized.lead}</p><div className="hero-actions"><a className="button button-primary" href={href}>{label} <span aria-hidden="true">↗</span></a></div></section>;
}

function Faq({ items }: { items: ReadonlyArray<{ question: string; answer: string }> }) {
  return <div className="faq-list">{items.map((item) => <details className="faq-item" key={item.question}><summary>{item.question}</summary><p>{item.answer}</p></details>)}</div>;
}

